/bin/bash -lc 'HEAD0=$("$HORIZON_GIT" rev-parse HEAD)
export HEAD0
python - <<'"'PY'
import io,json,os,re,subprocess,tarfile
from collections import Counter
from archon_horizon.search.index import extract_declarations
HG=\"/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/bin/hgit\"; ROOT=\"/home/axel/LeanAlgebraicGeometry-Horizon\"
BASE=\"c56d433e8a99a82babf50aecb3e6fec48410e2a2\"; HEAD=os.environ[\"HEAD0\"]
def split(sig):
 d=0
 for i,ch in enumerate(sig):
  if ch in \"([{\": d+=1
  elif ch in \")]}\": d=max(0,d-1)
  elif ch==\":\" and d==0:return sig[:i],sig[i+1:]
 return sig,\"\"
def snap(c,proj):
 p=f\"MainProjects/{proj}/AlgebraicJacobian\"
 raw=subprocess.check_output([HG,\"archive\",\"--format=tar\",c,p],cwd=ROOT)
 files=0; strict=0; ds={}
 with tarfile.open(fileobj=io.BytesIO(raw),mode=\"r:\") as tf:
  for m in tf:
   if not m.isfile() or not m.name.endswith(\".lean\"):continue
   files+=1; txt=tf.extractfile(m).read().decode()
   strict+=txt.count(\"(rep :\")
   for d in extract_declarations(txt,library=proj,file=m.name):
    a,b=split(d.signature)
    ds[(m.name,d.name)]=(a.count(\".RepresentableBy\"),b.count(\".RepresentableBy\"),d.name,m.name,d.line)
 cons={k:v for k,v in ds.items() if v[0]}
 res={k:v for k,v in ds.items() if v[1]}
 prod={k:v for k,v in res.items() if not v[0]}
 return dict(files=files,strict=strict,input=sum(v[0] for v in ds.values()),cons=cons,res=res,prod=prod)
print(\"FROZEN_HEAD\",HEAD)
for proj in [\"Algebraic-Jacobian-Challenge\",\"Algebraic-Jacobian-Challenge-Rebuild\"]:
 b=snap(BASE,proj); h=snap(HEAD,proj)
 def row(x):return dict(files=x[\"files\"],strict=x[\"strict\"],input_occ=x[\"input\"],consumer_decls=len(x[\"cons\"]),result_decls=len(x[\"res\"]),direct_result_producers=len(x[\"prod\"]))
 print(\"PROJECT\",proj)
 print(\"BASE\",json.dumps(row(b),sort_keys=True))
 print(\"HEAD\",json.dumps(row(h),sort_keys=True))
 print(\"DELTA\",json.dumps({k:row(h)[k]-row(b)[k] for k in row(b)},sort_keys=True))
 new={k:v for k,v in h[\"cons\"].items() if k not in b[\"cons\"]}
 print(\"NEW_CONSUMERS\",len(new))
 for f,n in sorted(Counter(v[3] for v in new.values()).items()): print(\" \",n,f)
 newp={k:v for k,v in h[\"prod\"].items() if k not in b[\"prod\"]}
 print(\"NEW_DIRECT_RESULT_PRODUCERS\",len(newp))
 for v in newp.values(): print(\" \",v[2],v[3],v[4])
PY
HEAD1="'$("$HORIZON_GIT" rev-parse HEAD)
echo "HEAD_AFTER=$HEAD1"
[ "$HEAD0" = "$HEAD1" ] || echo "HEAD_MOVED_DURING_MEASURE=1"'

/bin/bash -lc '"$HORIZON_BIN" ps --json 2>/dev/null | jq -r '"'.processes[] | [.run,.status,.alive,.idle_s] | @tsv'; python - <<'PY'
import subprocess,datetime,os
HG=\"/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/bin/hgit\"; base=\"c56d433e8a99a82babf50aecb3e6fec48410e2a2\"
out=subprocess.check_output([HG,\"log\",\"--format=%H%x09%aI%x09%(trailers:key=Archon-Task,valueonly)%x09%(trailers:key=Archon-Commit,valueonly)%x09%s\",base+\"..HEAD\"],text=True)
by={}
for line in out.splitlines():
 p=line.split(\"\\t\",4)
 if len(p)<5:continue
 h,ts,task,kind,sub=p
 if task in {\"pic-c\",\"pic-d\",\"pic-g\",\"pic-h\",\"rev-ajcr\",\"pic-a\",\"pic-b\",\"pic-e\",\"pic-f\"} and kind.strip()"'!="integration":
  by.setdefault(task,[]).append((datetime.datetime.fromisoformat(ts),h[:10],sub))
for t,v in sorted(by.items()):
 v.sort(); gaps=[]
 for a,b in zip(v,v[1:]):gaps.append((b[0]-a[0]).total_seconds()/60)
 print(t,"commits",len(v),"first",v[0][0].isoformat(),"last",v[-1][0].isoformat(),"max_gap_min",round(max(gaps) if gaps else 0,1))
PY'

